/**
 * Correct the 52 annual province articles in place (see
 * annual-accident-articles.ts). URL, publishedAt and updatedAt stay as they
 * are; only the body changes.
 *
 *   npx tsx scripts/correct-annual-accident-articles.ts                    # dry run
 *   npx tsx scripts/correct-annual-accident-articles.ts --apply --expect 52
 *
 * The rows, exactly (the backup takes the same filter):
 *   status = 'PUBLISHED' AND "isAutoGenerated" = true
 *   AND category = 'ANNUAL_REPORT' AND slug LIKE 'accidentalidad-%'
 *
 * The dry run prints how many change and one sample diff. --apply refuses
 * while any article has a structure it doesn't know, runs one transaction,
 * updates each row only if its body is still the one read, and rolls back
 * unless exactly --expect rows changed.
 */

import pg from "pg";
import { rewriteAnnualArticle } from "./annual-accident-articles.js";

interface Row {
  id: string;
  slug: string;
  province: string | null;
  body: string;
}

function sampleDiff(before: string, after: string): string {
  const a = before.split("\n");
  const b = after.split("\n");
  return [...a.filter((l) => !b.includes(l)).map((l) => `  - ${l}`), ...b.filter((l) => !a.includes(l)).map((l) => `  + ${l}`)].join("\n");
}

async function main() {
  const args = process.argv.slice(2);
  const apply = args.includes("--apply");
  const expect = Number(args[args.indexOf("--expect") + 1]);
  if (apply && !(args.includes("--expect") && Number.isInteger(expect) && expect > 0)) {
    throw new Error("--apply needs --expect <count> from the dry run");
  }
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set");

  const pool = new pg.Pool({ connectionString: url, max: 1 });
  const client = await pool.connect();
  try {
    const found = await client.query(
      `SELECT id, slug, province, body FROM "Article"
       WHERE status = 'PUBLISHED' AND "isAutoGenerated" = true
         AND category = 'ANNUAL_REPORT' AND slug LIKE 'accidentalidad-%'
       ORDER BY slug`
    );
    const rows = found.rows as Row[];

    const changes: { row: Row; body: string }[] = [];
    const refused: string[] = [];
    let same = 0;
    let sample = "";
    for (const row of rows) {
      const body = row.province ? rewriteAnnualArticle(row.province, row.body) : null;
      if (body == null) {
        refused.push(row.slug);
        continue;
      }
      if (body === row.body) {
        same++;
        continue;
      }
      changes.push({ row, body });
      if (!sample) sample = `${row.slug}\n${sampleDiff(row.body, body)}`;
    }

    console.log(`${rows.length} read, ${changes.length} to correct, ${same} already correct, ${refused.length} refused`);
    for (const slug of refused.slice(0, 5)) console.log(`  refused: ${slug}`);
    if (sample) console.log(`\nsample: ${sample}`);

    if (!apply) {
      console.log(`\ndry run: nothing written. Apply with --apply --expect ${changes.length}`);
      return;
    }
    if (refused.length > 0) throw new Error(`${refused.length} articles have a structure this doesn't know: handle them first`);

    await client.query("BEGIN");
    let updated = 0;
    for (const c of changes) {
      const r = await client.query(
        `UPDATE "Article" SET body = $1 WHERE id = $2 AND body = $3 AND status = 'PUBLISHED'`,
        [c.body, c.row.id, c.row.body]
      );
      updated += r.rowCount ?? 0;
    }
    if (updated !== expect) {
      await client.query("ROLLBACK");
      throw new Error(`would correct ${updated}, expected ${expect}: rolled back`);
    }
    await client.query("COMMIT");
    console.log(`corrected ${updated} (committed ${new Date().toISOString()})`);
  } catch (err) {
    await client.query("ROLLBACK").catch(() => {});
    throw err;
  } finally {
    client.release();
    await pool.end();
  }
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});
